import { prisma } from '@tpmjs/db';
import { type NextRequest, NextResponse } from 'next/server';
import { checkRateLimit, STRICT_RATE_LIMIT } from '~/lib/rate-limit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

// BM25 parameters
const k1 = 1.5; // term frequency saturation parameter
const b = 0.75; // length normalization parameter

// Split camelCase and PascalCase into words
function splitCamelCase(text: string): string {
  return text
    .replace(/([a-z])([A-Z])/g, '$1 $2') // camelCase -> camel Case
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2'); // XMLParser -> XML Parser
}

// Tokenize text into words (handles camelCase)
function tokenize(text: string): string[] {
  return splitCamelCase(text)
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter((t) => t.length > 0);
}

// Check for exact tool name match (case-insensitive)
function hasExactNameMatch(query: string, toolName: string): boolean {
  const queryLower = query.toLowerCase();
  const nameLower = toolName.toLowerCase();
  return queryLower.includes(nameLower) || nameLower.includes(queryLower);
}

// Check for package name match (case-insensitive)
function hasPackageNameMatch(query: string, packageName: string): boolean {
  const queryLower = query.toLowerCase();
  const packageLower = packageName.toLowerCase();
  // Check if query contains package name or package name contains query
  // Also handle partial matches like "@tpmjs/tools-" matching "@tpmjs/tools-unsandbox"
  return queryLower.includes(packageLower) || packageLower.includes(queryLower);
}

// Calculate term frequency
function termFrequency(term: string, tokens: string[]): number {
  return tokens.filter((t) => t === term).length;
}

// Calculate BM25 score
function calculateBM25(
  query: string,
  document: string,
  avgDocLength: number,
  totalDocs: number,
  docFrequencies: Map<string, number>
): number {
  const queryTokens = tokenize(query);
  const docTokens = tokenize(document);
  const docLength = docTokens.length;

  let score = 0;

  for (const term of queryTokens) {
    const tf = termFrequency(term, docTokens);
    if (tf === 0) continue;

    // IDF calculation
    const docFreq = docFrequencies.get(term) || 0;
    const idf = Math.log((totalDocs - docFreq + 0.5) / (docFreq + 0.5) + 1);

    // BM25 formula
    const numerator = tf * (k1 + 1);
    const denominator = tf + k1 * (1 - b + b * (docLength / avgDocLength));

    score += idf * (numerator / denominator);
  }

  return score;
}

export async function GET(request: NextRequest) {
  console.log('🔎 [SEARCH API] Request received');

  // Check rate limit (stricter limit for expensive search operations)
  const rateLimitResponse = checkRateLimit(request, STRICT_RATE_LIMIT);
  if (rateLimitResponse) {
    return rateLimitResponse;
  }

  try {
    const { searchParams } = new URL(request.url);
    // Accept both 'q' and 'query' parameters for flexibility
    const query = searchParams.get('q') || searchParams.get('query') || '';
    const category = searchParams.get('category');
    const limit = Math.min(Number.parseInt(searchParams.get('limit') || '10', 10), 100);

    // Parse excludeIds to filter out tools already in user's collection
    const excludeIdsParam = searchParams.get('excludeIds');
    const excludeIds = excludeIdsParam ? excludeIdsParam.split(',').filter(Boolean) : [];

    // Get recent messages for context (passed as JSON in 'messages' param)
    // Wrap in try-catch to handle malformed JSON gracefully
    const messagesParam = searchParams.get('messages');
    let recentMessages: string[] = [];
    if (messagesParam) {
      try {
        const parsed = JSON.parse(messagesParam);
        if (Array.isArray(parsed)) {
          recentMessages = parsed.filter((m): m is string => typeof m === 'string');
        }
      } catch {
        console.warn('[SEARCH API] Failed to parse messages param, ignoring');
      }
    }

    console.log(
      `🔎 [SEARCH API] Query: "${query}", Category: ${category}, Limit: ${limit}, Messages: ${recentMessages.length}`
    );

    // Extract search tokens for database-level pre-filtering
    const searchTokens = tokenize(query).filter((t) => t.length >= 2);
    const hasSearchQuery = searchTokens.length > 0;

    // Build database filter - pre-filter at DB level to reduce in-memory processing
    // Use OR conditions to find tools that match ANY search token
    const dbFilter = {
      // Exclude tools already in collection (if provided)
      ...(excludeIds.length > 0 && { id: { notIn: excludeIds } }),
      ...(category && { package: { category } }),
      ...(hasSearchQuery && {
        OR: [
          // Match tool name
          { name: { contains: query, mode: 'insensitive' as const } },
          // Match tool description
          { description: { contains: query, mode: 'insensitive' as const } },
          // Match package name
          { package: { npmPackageName: { contains: query, mode: 'insensitive' as const } } },
          // Match package description
          { package: { npmDescription: { contains: query, mode: 'insensitive' as const } } },
          // Also try individual tokens for partial matches
          ...searchTokens
            .slice(0, 3)
            .flatMap((token) => [
              { name: { contains: token, mode: 'insensitive' as const } },
              { description: { contains: token, mode: 'insensitive' as const } },
            ]),
        ],
      }),
    };

    // Fetch filtered tools with package info (max 500 for BM25 scoring)
    const tools = await prisma.tool.findMany({
      include: { package: true },
      where: dbFilter,
      take: hasSearchQuery ? 500 : 100, // Limit results for performance
      orderBy: hasSearchQuery ? undefined : { qualityScore: 'desc' },
    });

    console.log(`📊 [SEARCH API] Found ${tools.length} tools in database`);

    // Combine query with recent messages for better context
    const fullQuery = [query, ...recentMessages].filter(Boolean).join(' ');
    console.log(`🔍 [SEARCH API] Full search context: "${fullQuery.slice(0, 100)}..."`);

    // Build all documents first
    const documents = tools.map((tool) => ({
      tool,
      text: [
        tool.description,
        tool.name,
        tool.package.npmPackageName,
        tool.package.npmDescription || '',
        ...(tool.package.npmKeywords || []),
      ].join(' '),
    }));

    // Calculate document frequencies (IDF)
    const docFrequencies = new Map<string, number>();
    const queryTokens = tokenize(fullQuery);

    for (const term of queryTokens) {
      let count = 0;
      for (const doc of documents) {
        const docTokens = tokenize(doc.text);
        if (docTokens.includes(term)) {
          count++;
        }
      }
      docFrequencies.set(term, count);
    }

    // Calculate average document length
    const totalTokens = documents.reduce((sum, doc) => sum + tokenize(doc.text).length, 0);
    const avgDocLength = totalTokens / documents.length;

    // Calculate BM25 scores
    const scoredResults = documents.map(({ tool, text }) => {
      const bm25Score = calculateBM25(fullQuery, text, avgDocLength, tools.length, docFrequencies);
      const qualityBoost = Number(tool.qualityScore ?? 0) * 0.5;
      const downloadBoost = Math.log10((tool.package.npmDownloadsLastMonth || 0) + 1) * 0.1;

      // Massive boost for exact tool name match (when user mentions tool by name)
      const exactNameBoost = hasExactNameMatch(query, tool.name) ? 100 : 0;

      // Boost for package name match (when user searches by package name like @tpmjs/tools-unsandbox)
      const packageNameBoost = hasPackageNameMatch(query, tool.package.npmPackageName) ? 50 : 0;

      const finalScore =
        bm25Score + qualityBoost + downloadBoost + exactNameBoost + packageNameBoost;

      return { tool, score: finalScore };
    });

    // Sort by score and take top N
    const topResults = scoredResults
      .filter(({ score }) => score > 0) // Only include results with matches
      .sort((a, b) => b.score - a.score)
      .slice(0, limit + 1);

    const hasMore = topResults.length > limit;
    const results = hasMore ? topResults.slice(0, limit) : topResults;

    console.log(`✅ [SEARCH API] Returning ${results.length} results (hasMore: ${hasMore})`);

    // Format response to match existing /api/tools structure
    return NextResponse.json({
      success: true,
      query,
      filters: { category },
      results: {
        total: scoredResults.filter(({ score }) => score > 0).length,
        returned: results.length,
        tools: results.map(({ tool }) => ({
          id: tool.id,
          name: tool.name,
          description: tool.description,
          inputSchema: tool.inputSchema,
          qualityScore: tool.qualityScore,
          importHealth: tool.importHealth,
          executionHealth: tool.executionHealth,
          healthCheckError: tool.healthCheckError,
          lastHealthCheck: tool.lastHealthCheck,
          package: {
            npmPackageName: tool.package.npmPackageName,
            npmVersion: tool.package.npmVersion,
            category: tool.package.category,
            frameworks: tool.package.frameworks,
            env: tool.package.env,
            npmRepository: tool.package.npmRepository,
            isOfficial: tool.package.isOfficial,
            npmDownloadsLastMonth: tool.package.npmDownloadsLastMonth,
          },
          importUrl: `https://esm.sh/${tool.package.npmPackageName}@${tool.package.npmVersion}`,
          cdnUrl: `https://cdn.jsdelivr.net/npm/${tool.package.npmPackageName}@${tool.package.npmVersion}/+esm`,
        })),
      },
      pagination: {
        limit,
        hasMore,
      },
    });
  } catch (error) {
    console.error('❌ [SEARCH API] Error:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Search failed',
      },
      { status: 500 }
    );
  }
}

import { prisma } from '@tpmjs/db';
import { type NextRequest, NextResponse } from 'next/server';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

/**
 * POST /api/sync/stats-snapshot
 * Captures a daily snapshot of registry statistics for historical tracking.
 * Should be run once per day via cron.
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: cron handler with many parallel queries
export async function POST(request: NextRequest) {
  const startTime = Date.now();

  // Verify cron secret
  const authHeader = request.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET;

  if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    // Get today's date at midnight UTC
    const today = new Date();
    today.setUTCHours(0, 0, 0, 0);

    // Check if we already have a snapshot for today
    const existingSnapshot = await prisma.statsSnapshot.findUnique({
      where: { date: today },
    });

    if (existingSnapshot) {
      return NextResponse.json({
        success: true,
        message: 'Snapshot already exists for today',
        data: { date: today.toISOString(), id: existingSnapshot.id },
      });
    }

    // Time boundaries for daily counts
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    // Gather all statistics in parallel
    const [
      // Tool and package counts
      totalTools,
      totalPackages,
      officialTools,
      officialPackages,
      toolsWithSchema,

      // Health status counts
      importHealthy,
      importBroken,
      importUnknown,
      executionHealthy,
      executionBroken,
      executionUnknown,

      // Package data for aggregations
      packages,

      // Daily execution stats
      dailyExecutions,
      dailySuccessful,
      dailyFailed,
      avgExecutionTime,

      // Daily token usage
      dailyTokens,

      // Daily health checks
      dailyHealthChecks,

      // Social proof
      activeDevsResult,
      publicCollectionsCount,
      publicAgentsCount,
      totalSimulationsCount,

      // Execution events (daily)
      eventToolCallsCount,
      eventAgentRunsCount,

      // Quality distribution
      qualityDistribution,
    ] = await Promise.all([
      // Tool counts
      prisma.tool.count(),
      prisma.package.count(),
      prisma.tool.count({ where: { package: { isOfficial: true } } }),
      prisma.package.count({ where: { isOfficial: true } }),
      prisma.tool.count({ where: { schemaSource: 'extracted' } }),

      // Health status
      prisma.tool.count({ where: { importHealth: 'HEALTHY' } }),
      prisma.tool.count({ where: { importHealth: 'BROKEN' } }),
      prisma.tool.count({ where: { importHealth: 'UNKNOWN' } }),
      prisma.tool.count({ where: { executionHealth: 'HEALTHY' } }),
      prisma.tool.count({ where: { executionHealth: 'BROKEN' } }),
      prisma.tool.count({ where: { executionHealth: 'UNKNOWN' } }),

      // Package data
      prisma.package.findMany({
        select: {
          tier: true,
          category: true,
          npmDownloadsLastMonth: true,
          githubStars: true,
          _count: { select: { tools: true } },
        },
      }),

      // Daily execution stats
      prisma.simulation.count({
        where: { createdAt: { gte: yesterday, lt: today } },
      }),
      prisma.simulation.count({
        where: { createdAt: { gte: yesterday, lt: today }, status: 'success' },
      }),
      prisma.simulation.count({
        where: {
          createdAt: { gte: yesterday, lt: today },
          status: { in: ['error', 'timeout'] },
        },
      }),
      prisma.simulation.aggregate({
        where: {
          createdAt: { gte: yesterday, lt: today },
          status: 'success',
          executionTimeMs: { not: null },
        },
        _avg: { executionTimeMs: true },
      }),

      // Daily token usage
      prisma.tokenUsage.aggregate({
        where: { createdAt: { gte: yesterday, lt: today } },
        _sum: {
          inputTokens: true,
          outputTokens: true,
          totalTokens: true,
          estimatedCost: true,
        },
      }),

      // Daily health checks
      prisma.healthCheck.count({
        where: { createdAt: { gte: yesterday, lt: today } },
      }),

      // Social proof fields
      prisma.userActivity.groupBy({
        by: ['userId'],
        where: {
          createdAt: { gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) },
        },
      }),
      prisma.collection.count({ where: { isPublic: true } }),
      prisma.agent.count({ where: { isPublic: true } }),
      prisma.simulation.count(),

      // Execution events (daily counts from ExecutionEvent table)
      prisma.executionEvent.count({
        where: { createdAt: { gte: yesterday, lt: today }, eventType: 'tool_call' },
      }),
      prisma.executionEvent.count({
        where: { createdAt: { gte: yesterday, lt: today }, eventType: 'agent_run' },
      }),

      // Quality score distribution
      prisma.$queryRaw<{ bucket: string; count: bigint }[]>`
        SELECT
          CASE
            WHEN quality_score IS NULL THEN 'unscored'
            WHEN quality_score < 0.3 THEN 'low'
            WHEN quality_score < 0.5 THEN 'medium-low'
            WHEN quality_score < 0.7 THEN 'medium'
            WHEN quality_score < 0.9 THEN 'high'
            ELSE 'excellent'
          END as bucket,
          COUNT(*) as count
        FROM tools
        GROUP BY
          CASE
            WHEN quality_score IS NULL THEN 'unscored'
            WHEN quality_score < 0.3 THEN 'low'
            WHEN quality_score < 0.5 THEN 'medium-low'
            WHEN quality_score < 0.7 THEN 'medium'
            WHEN quality_score < 0.9 THEN 'high'
            ELSE 'excellent'
          END
      `,
    ]);

    // Aggregate package data
    let tiersMinimal = 0;
    let tiersRich = 0;
    let totalNpmDownloads = 0;
    let totalGithubStars = 0;
    const categories: Record<string, number> = {};

    for (const pkg of packages) {
      if (pkg.tier === 'minimal') tiersMinimal++;
      if (pkg.tier === 'rich') tiersRich++;
      totalNpmDownloads += pkg.npmDownloadsLastMonth || 0;
      totalGithubStars += pkg.githubStars || 0;

      if (pkg.category) {
        categories[pkg.category] = (categories[pkg.category] || 0) + pkg._count.tools;
      }
    }

    // Format quality distribution
    const qualityDist: Record<string, number> = {};
    for (const row of qualityDistribution) {
      qualityDist[row.bucket] = Number(row.count);
    }

    // Create the snapshot
    const snapshot = await prisma.statsSnapshot.create({
      data: {
        date: today,

        // Registry overview
        totalTools,
        totalPackages,
        officialTools,
        officialPackages,
        toolsWithSchema,

        // Downloads & stars
        totalNpmDownloads,
        totalGithubStars,

        // Health status
        importHealthy,
        importBroken,
        importUnknown,
        executionHealthy,
        executionBroken,
        executionUnknown,

        // Quality distribution
        qualityDistribution: qualityDist,

        // Tiers
        tiersMinimal,
        tiersRich,

        // Daily execution stats
        executionsTotal: dailyExecutions,
        executionsSuccessful: dailySuccessful,
        executionsFailed: dailyFailed,
        executionsAvgTimeMs: avgExecutionTime._avg.executionTimeMs
          ? Math.round(avgExecutionTime._avg.executionTimeMs)
          : null,

        // Daily token usage
        tokensInput: BigInt(dailyTokens._sum.inputTokens || 0),
        tokensOutput: BigInt(dailyTokens._sum.outputTokens || 0),
        tokensTotal: BigInt(dailyTokens._sum.totalTokens || 0),
        tokensCostUsd: dailyTokens._sum.estimatedCost,

        // Daily health checks
        healthChecksRun: dailyHealthChecks,

        // Categories
        categories,

        // Social proof
        activeDevs7d: activeDevsResult.length,
        totalCollections: publicCollectionsCount,
        totalAgents: publicAgentsCount,
        totalSimulations: totalSimulationsCount,

        // Execution event counts
        eventToolCalls: eventToolCallsCount,
        eventAgentRuns: eventAgentRunsCount,
      },
    });

    const processingTime = Date.now() - startTime;

    return NextResponse.json({
      success: true,
      data: {
        id: snapshot.id,
        date: snapshot.date,
        totalTools: snapshot.totalTools,
        totalPackages: snapshot.totalPackages,
        executionsTotal: snapshot.executionsTotal,
        processingTimeMs: processingTime,
      },
    });
  } catch (error) {
    console.error('Error creating stats snapshot:', error);

    return NextResponse.json(
      {
        success: false,
        error: {
          code: 'SNAPSHOT_ERROR',
          message: 'Failed to create stats snapshot',
          details: error instanceof Error ? error.message : 'Unknown error',
        },
      },
      { status: 500 }
    );
  }
}

// GET endpoint to retrieve recent snapshots
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const days = Math.min(parseInt(searchParams.get('days') || '30', 10), 365);

  try {
    const since = new Date();
    since.setDate(since.getDate() - days);

    const snapshots = await prisma.statsSnapshot.findMany({
      where: { date: { gte: since } },
      orderBy: { date: 'asc' },
    });

    // Convert BigInt to number for JSON serialization
    const serializedSnapshots = snapshots.map((s) => ({
      ...s,
      tokensInput: Number(s.tokensInput),
      tokensOutput: Number(s.tokensOutput),
      tokensTotal: Number(s.tokensTotal),
    }));

    return NextResponse.json({
      success: true,
      data: {
        snapshots: serializedSnapshots,
        count: snapshots.length,
        days,
      },
    });
  } catch (error) {
    console.error('Error fetching stats snapshots:', error);

    return NextResponse.json(
      {
        success: false,
        error: {
          code: 'FETCH_ERROR',
          message: 'Failed to fetch stats snapshots',
          details: error instanceof Error ? error.message : 'Unknown error',
        },
      },
      { status: 500 }
    );
  }
}

