  1→import type { ActivityType } from '@prisma/client';
  2→import { prisma } from '@tpmjs/db';
  3→import { headers } from 'next/headers';
  4→import { type NextRequest, NextResponse } from 'next/server';
  5→import { auth } from '~/lib/auth';
  6→
  7→export const runtime = 'nodejs';
  8→export const dynamic = 'force-dynamic';
  9→export const maxDuration = 60;
 10→
 11→const API_VERSION = '1.0.0';
 12→
 13→interface ApiResponse<T = unknown> {
 14→  success: boolean;
 15→  data?: T;
 16→  error?: {
 17→    code: string;
 18→    message: string;
 19→    details?: Record<string, unknown>;
 20→  };
 21→  meta: {
 22→    version: string;
 23→    timestamp: string;
 24→    requestId?: string;
 25→  };
 26→  pagination?: {
 27→    limit: number;
 28→    hasMore: boolean;
 29→    nextCursor?: string | null;
 30→  };
 31→}
 32→
 33→/**
 34→ * GET /api/user/activity
 35→ * Get activity stream for the current user
 36→ *
 37→ * Query params:
 38→ * - limit: number (1-50, default 20)
 39→ * - cursor: string (activity ID for cursor-based pagination)
 40→ */
 41→export async function GET(request: NextRequest): Promise<NextResponse<ApiResponse>> {
 42→  const requestId = crypto.randomUUID();
 43→
 44→  try {
 45→    const session = await auth.api.getSession({
 46→      headers: await headers(),
 47→    });
 48→
 49→    if (!session) {
 50→      return NextResponse.json(
 51→        {
 52→          success: false,
 53→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
 54→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 55→        },
 56→        { status: 401 }
 57→      );
 58→    }
 59→
 60→    const { searchParams } = new URL(request.url);
 61→    const limit = Math.min(Math.max(Number.parseInt(searchParams.get('limit') || '20', 10), 1), 50);
 62→    const cursor = searchParams.get('cursor');
 63→    const targetType = searchParams.get('targetType');
 64→    const type = searchParams.get('type');
 65→
 66→    const activities = await prisma.userActivity.findMany({
 67→      where: {
 68→        userId: session.user.id,
 69→        ...(targetType && { targetType }),
 70→        ...(type && { type: type as ActivityType }),
 71→      },
 72→      orderBy: { createdAt: 'desc' },
 73→      take: limit + 1,
 74→      ...(cursor && {
 75→        cursor: { id: cursor },
 76→        skip: 1, // Skip the cursor item itself
 77→      }),
 78→      select: {
 79→        id: true,
 80→        type: true,
 81→        targetName: true,
 82→        targetType: true,
 83→        agentId: true,
 84→        collectionId: true,
 85→        toolId: true,
 86→        metadata: true,
 87→        createdAt: true,
 88→      },
 89→    });
 90→
 91→    const hasMore = activities.length > limit;
 92→    const data = hasMore ? activities.slice(0, limit) : activities;
 93→    const nextCursor = hasMore && data.length > 0 ? data[data.length - 1]?.id : null;
 94→
 95→    return NextResponse.json({
 96→      success: true,
 97→      data,
 98→      pagination: {
 99→        limit,
100→        hasMore,
101→        nextCursor,
102→      },
103→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
104→    });
105→  } catch (error) {
106→    console.error('[API Error] GET /api/user/activity:', error);
107→    return NextResponse.json(
108→      {
109→        success: false,
110→        error: { code: 'INTERNAL_ERROR', message: 'Failed to fetch activity' },
111→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
112→      },
113→      { status: 500 }
114→    );
115→  }
116→}
