 10→/**
 11→ * GET /api/user/activity-dashboard
 12→ * Returns all dashboard data in one request.
 13→ *
 14→ * Query params:
 15→ * - period: '7d' | '30d' | '90d' (default '30d')
 16→ */
 17→export async function GET(request: NextRequest) {
 18→  try {
 19→    const session = await auth.api.getSession({ headers: await headers() });
 20→    if (!session?.user?.id) {
 21→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 22→    }
 23→
 24→    const userId = session.user.id;
 25→    const { searchParams } = new URL(request.url);
 26→    const period = searchParams.get('period') || '30d';
 27→
 28→    const days = period === '7d' ? 7 : period === '90d' ? 90 : 30;
 29→    const since = new Date();
 30→    since.setDate(since.getDate() - days);
 31→
 32→    const [
 33→      executionSummary,
 34→      conversationCount,
 35→      apiUsageSummary,
 36→      executionTimeline,
 37→      topTools,
 38→      topAgents,
 39→      recentErrors,
 40→    ] = await Promise.all([
 41→      // 1. Execution summary
 42→      prisma.executionEvent.groupBy({
 43→        by: ['status'],
 44→        where: { userId, createdAt: { gte: since } },
 45→        _count: { id: true },
 46→      }),
 47→
 48→      // 2. Conversation count (via user's agents)
 49→      prisma.conversation.count({
 50→        where: {
 51→          agent: { userId },
 52→          createdAt: { gte: since },
 53→        },
 54→      }),
 55→
 56→      // 3. API usage summary
 57→      prisma.apiUsageSummary.aggregate({
 58→        where: { userId, periodStart: { gte: since } },
 59→        _sum: {
 60→          totalRequests: true,
 61→          totalTokensIn: true,
 62→          totalTokensOut: true,
 63→        },
 64→      }),
 65→
 66→      // 4. Execution timeline (group by date)
 67→      prisma.$queryRaw<
 68→        Array<{
 69→          date: string;
 70→          tool_calls: bigint;
 71→          agent_runs: bigint;
 72→          successes: bigint;
 73→          errors: bigint;
 74→        }>
 75→      >`
 76→        SELECT
 77→          DATE(created_at) as date,
 78→          COUNT(*) FILTER (WHERE event_type = 'tool_call') as tool_calls,
 79→          COUNT(*) FILTER (WHERE event_type = 'agent_run') as agent_runs,
 80→          COUNT(*) FILTER (WHERE status = 'success') as successes,
 81→          COUNT(*) FILTER (WHERE status = 'error') as errors
 82→        FROM execution_events
 83→        WHERE user_id = ${userId}
 84→          AND created_at >= ${since}
 85→        GROUP BY DATE(created_at)
 86→        ORDER BY date ASC
 87→      `,
 88→
 89→      // 5. Top tools
 90→      prisma.executionEvent.groupBy({
 91→        by: ['toolName', 'packageName'],
 92→        where: { userId, createdAt: { gte: since }, toolName: { not: null } },
 93→        _count: { id: true },
 94→        _max: { createdAt: true },
 95→        orderBy: { _count: { id: 'desc' } },
 96→        take: 10,
 97→      }),
 98→
 99→      // 6. Top agents
100→      prisma.agent.findMany({
101→        where: { userId },
102→        select: {
103→          id: true,
104→          name: true,
105→          uid: true,
106→          conversationCount: true,
107→          messageCount: true,
108→          _count: {
109→            select: {
110→              conversations: {
111→                where: { createdAt: { gte: since } },
112→              },
113→            },
114→          },
115→        },
116→        orderBy: { conversationCount: 'desc' },
117→        take: 10,
118→      }),
119→
120→      // 7. Recent errors
121→      prisma.executionEvent.groupBy({
122→        by: ['toolName', 'errorMessage'],
123→        where: {
124→          userId,
125→          status: 'error',
126→          createdAt: { gte: since },
127→          toolName: { not: null },
128→        },
129→        _count: { id: true },
130→        _max: { createdAt: true },
131→        orderBy: { _count: { id: 'desc' } },
132→        take: 10,
133→      }),
134→    ]);
135→
136→    // Calculate summary
137→    const totalExecutions = executionSummary.reduce((sum, e) => sum + e._count.id, 0);
138→    const successCount = executionSummary.find((e) => e.status === 'success')?._count.id ?? 0;
139→    const successRate =
140→      totalExecutions > 0 ? Math.round((successCount / totalExecutions) * 100) : 0;
141→    const totalTokens =
142→      (apiUsageSummary._sum.totalTokensIn ?? 0) + (apiUsageSummary._sum.totalTokensOut ?? 0);
143→
144→    return NextResponse.json({
145→      success: true,
146→      data: {
147→        summary: {
148→          totalToolExecutions: totalExecutions,
149→          totalAgentConversations: conversationCount,
150→          totalApiRequests: apiUsageSummary._sum.totalRequests ?? 0,
151→          successRate,
152→          totalTokensUsed: totalTokens,
153→        },
154→        executionTimeline: executionTimeline.map((row) => ({
155→          date: row.date,
156→          toolCalls: Number(row.tool_calls),
157→          agentRuns: Number(row.agent_runs),
158→          successes: Number(row.successes),
159→          errors: Number(row.errors),
160→        })),
161→        topTools: topTools.map((t) => ({
162→          toolName: t.toolName,
163→          packageName: t.packageName,
164→          count: t._count.id,
165→          lastUsed: t._max.createdAt,
166→        })),
167→        topAgents: topAgents.map((a) => ({
168→          agentName: a.name,
169→          agentUid: a.uid,
170→          agentId: a.id,
171→          conversationCount: a._count.conversations,
172→          totalConversations: a.conversationCount,
173→          messageCount: a.messageCount,
174→        })),
175→        recentErrors: recentErrors.map((e) => ({
176→          toolName: e.toolName,
177→          errorMessage: e.errorMessage,
178→          count: e._count.id,
179→          lastOccurred: e._max.createdAt,
180→        })),
181→      },
182→    });
183→  } catch (error) {
184→    console.error('[activity-dashboard] Error:', error);
185→    return NextResponse.json(
186→      { success: false, error: 'Failed to fetch activity dashboard' },
187→      { status: 500 }
188→    );
189→  }
190→}
