import { prisma } from '@tpmjs/db';
import { type NextRequest, NextResponse } from 'next/server';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

/**
 * POST /api/sync/stats-snapshot
 * Captures a daily snapshot of registry statistics for historical tracking.
 * Should be run once per day via cron.
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: cron handler with many parallel queries
export async function POST(request: NextRequest) {
  const startTime = Date.now();

  // Verify cron secret
  const authHeader = request.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET;

  if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    // Get today's date at midnight UTC
    const today = new Date();
    today.setUTCHours(0, 0, 0, 0);

    // Check if we already have a snapshot for today
    const existingSnapshot = await prisma.statsSnapshot.findUnique({
      where: { date: today },
    });

    if (existingSnapshot) {
      return NextResponse.json({
        success: true,
        message: 'Snapshot already exists for today',
        data: { date: today.toISOString(), id: existingSnapshot.id },
      });
    }

    // Time boundaries for daily counts
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    // Gather all statistics in parallel
    const [
      // Tool and package counts
      totalTools,
      totalPackages,
      officialTools,
      officialPackages,
      toolsWithSchema,

      // Health status counts
      importHealthy,
      importBroken,
      importUnknown,
      executionHealthy,
      executionBroken,
      executionUnknown,

      // Package data for aggregations
      packages,

      // Daily execution stats
      dailyExecutions,
      dailySuccessful,
      dailyFailed,
      avgExecutionTime,

      // Daily token usage
      dailyTokens,

      // Daily health checks
      dailyHealthChecks,

      // Social proof
      activeDevsResult,
      publicCollectionsCount,
      publicAgentsCount,
      totalSimulationsCount,

      // Execution events (daily)
      eventToolCallsCount,
      eventAgentRunsCount,

