      prisma.tool.count({ where: { importHealth: 'BROKEN' } }),
      prisma.tool.count({ where: { importHealth: 'UNKNOWN' } }),
      prisma.tool.count({ where: { executionHealth: 'HEALTHY' } }),
      prisma.tool.count({ where: { executionHealth: 'BROKEN' } }),
      prisma.tool.count({ where: { executionHealth: 'UNKNOWN' } }),

      // Package data
      prisma.package.findMany({
        select: {
          tier: true,
          category: true,
          npmDownloadsLastMonth: true,
          githubStars: true,
          _count: { select: { tools: true } },
        },
      }),

      // Daily execution stats
      prisma.simulation.count({
        where: { createdAt: { gte: yesterday, lt: today } },
      }),
      prisma.simulation.count({
        where: { createdAt: { gte: yesterday, lt: today }, status: 'success' },
      }),
      prisma.simulation.count({
        where: {
          createdAt: { gte: yesterday, lt: today },
          status: { in: ['error', 'timeout'] },
        },
      }),
      prisma.simulation.aggregate({
        where: {
          createdAt: { gte: yesterday, lt: today },
          status: 'success',
          executionTimeMs: { not: null },
        },
        _avg: { executionTimeMs: true },
      }),

      // Daily token usage
      prisma.tokenUsage.aggregate({
        where: { createdAt: { gte: yesterday, lt: today } },
        _sum: {
          inputTokens: true,
          outputTokens: true,
          totalTokens: true,
          estimatedCost: true,
        },
      }),

      // Daily health checks
      prisma.healthCheck.count({
        where: { createdAt: { gte: yesterday, lt: today } },
      }),

      // Social proof fields
      prisma.userActivity.groupBy({
        by: ['userId'],
        where: {
          createdAt: { gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) },
        },
      }),
      prisma.collection.count({ where: { isPublic: true } }),
      prisma.agent.count({ where: { isPublic: true } }),
      prisma.simulation.count(),

      // Execution events (daily counts from ExecutionEvent table)
      prisma.executionEvent.count({
        where: { createdAt: { gte: yesterday, lt: today }, eventType: 'tool_call' },
      }),
      prisma.executionEvent.count({
        where: { createdAt: { gte: yesterday, lt: today }, eventType: 'agent_run' },
      }),

      // DAU - distinct users active in last 24h
      prisma.userActivity.groupBy({
        by: ['userId'],
        where: { createdAt: { gte: yesterday, lt: today } },
      }),
      // WAU - distinct users active in last 7 days
      prisma.userActivity.groupBy({
        by: ['userId'],
        where: { createdAt: { gte: new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000) } },
      }),
      // MAU - distinct users active in last 30 days
      prisma.userActivity.groupBy({
        by: ['userId'],
        where: { createdAt: { gte: new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000) } },
      }),

      // Search volume (last 24h)
      prisma.searchLog.count({
        where: { createdAt: { gte: yesterday, lt: today } },
      }),
      // Average search latency
      prisma.searchLog.aggregate({
        where: { createdAt: { gte: yesterday, lt: today } },
        _avg: { latencyMs: true },
      }),
      // Top 10 search queries by frequency
      prisma.$queryRaw<{ query: string; count: bigint }[]>`
        SELECT query, COUNT(*) as count
        FROM search_logs
        WHERE created_at >= ${yesterday} AND created_at < ${today}
        GROUP BY query
        ORDER BY count DESC
        LIMIT 10
      `,

      // MCP unique clients (distinct userId or sessionId from ExecutionEvent where source starts with 'mcp')
      prisma.$queryRaw<{ count: bigint }[]>`
        SELECT COUNT(DISTINCT COALESCE(user_id, 'anon')) as count
        FROM execution_events
        WHERE source LIKE 'mcp_%'
          AND created_at >= ${new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000)}
      `,

      // Quality score distribution
      prisma.$queryRaw<{ bucket: string; count: bigint }[]>`
        SELECT
          CASE
            WHEN quality_score IS NULL THEN 'unscored'
            WHEN quality_score < 0.3 THEN 'low'
            WHEN quality_score < 0.5 THEN 'medium-low'
            WHEN quality_score < 0.7 THEN 'medium'
            WHEN quality_score < 0.9 THEN 'high'
            ELSE 'excellent'
          END as bucket,
          COUNT(*) as count
        FROM tools
        GROUP BY
          CASE
            WHEN quality_score IS NULL THEN 'unscored'
            WHEN quality_score < 0.3 THEN 'low'
            WHEN quality_score < 0.5 THEN 'medium-low'
            WHEN quality_score < 0.7 THEN 'medium'
            WHEN quality_score < 0.9 THEN 'high'
            ELSE 'excellent'
          END
      `,
    ]);

    // Aggregate package data
    let tiersMinimal = 0;
    let tiersRich = 0;
    let totalNpmDownloads = 0;
    let totalGithubStars = 0;
    const categories: Record<string, number> = {};

    for (const pkg of packages) {
      if (pkg.tier === 'minimal') tiersMinimal++;
      if (pkg.tier === 'rich') tiersRich++;
      totalNpmDownloads += pkg.npmDownloadsLastMonth || 0;
      totalGithubStars += pkg.githubStars || 0;

      if (pkg.category) {
        categories[pkg.category] = (categories[pkg.category] || 0) + pkg._count.tools;
      }
    }

    // Format quality distribution
    const qualityDist: Record<string, number> = {};
    for (const row of qualityDistribution) {
      qualityDist[row.bucket] = Number(row.count);
    }

    // Create the snapshot
    const snapshot = await prisma.statsSnapshot.create({
      data: {
        date: today,

        // Registry overview
        totalTools,
        totalPackages,
        officialTools,
        officialPackages,
        toolsWithSchema,

        // Downloads & stars
        totalNpmDownloads,
        totalGithubStars,

        // Health status
        importHealthy,
        importBroken,
        importUnknown,
        executionHealthy,
        executionBroken,
        executionUnknown,

        // Quality distribution
        qualityDistribution: qualityDist,

        // Tiers
        tiersMinimal,
        tiersRich,

        // Daily execution stats
        executionsTotal: dailyExecutions,
        executionsSuccessful: dailySuccessful,
        executionsFailed: dailyFailed,
        executionsAvgTimeMs: avgExecutionTime._avg.executionTimeMs
          ? Math.round(avgExecutionTime._avg.executionTimeMs)
          : null,

        // Daily token usage
        tokensInput: BigInt(dailyTokens._sum.inputTokens || 0),
        tokensOutput: BigInt(dailyTokens._sum.outputTokens || 0),
        tokensTotal: BigInt(dailyTokens._sum.totalTokens || 0),
        tokensCostUsd: dailyTokens._sum.estimatedCost,

        // Daily health checks
        healthChecksRun: dailyHealthChecks,

        // Categories
        categories,

        // Social proof
        activeDevs7d: activeDevsResult.length,
        totalCollections: publicCollectionsCount,
        totalAgents: publicAgentsCount,
        totalSimulations: totalSimulationsCount,

        // Execution event counts
        eventToolCalls: eventToolCallsCount,
        eventAgentRuns: eventAgentRunsCount,
      },
    });

    const processingTime = Date.now() - startTime;

    return NextResponse.json({
      success: true,
      data: {
        id: snapshot.id,
        date: snapshot.date,
        totalTools: snapshot.totalTools,
        totalPackages: snapshot.totalPackages,
        executionsTotal: snapshot.executionsTotal,
        processingTimeMs: processingTime,
      },
    });
  } catch (error) {
    console.error('Error creating stats snapshot:', error);

    return NextResponse.json(
      {
        success: false,
        error: {
          code: 'SNAPSHOT_ERROR',
          message: 'Failed to create stats snapshot',
          details: error instanceof Error ? error.message : 'Unknown error',
        },
      },
      { status: 500 }
    );
  }
}

// GET endpoint to retrieve recent snapshots
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const days = Math.min(parseInt(searchParams.get('days') || '30', 10), 365);

  try {
    const since = new Date();
    since.setDate(since.getDate() - days);

    const snapshots = await prisma.statsSnapshot.findMany({
      where: { date: { gte: since } },
      orderBy: { date: 'asc' },
    });

    // Convert BigInt to number for JSON serialization
    const serializedSnapshots = snapshots.map((s) => ({
      ...s,
      tokensInput: Number(s.tokensInput),
      tokensOutput: Number(s.tokensOutput),
      tokensTotal: Number(s.tokensTotal),
    }));

    return NextResponse.json({
      success: true,
      data: {
        snapshots: serializedSnapshots,
        count: snapshots.length,
        days,
      },
    });
  } catch (error) {
    console.error('Error fetching stats snapshots:', error);

    return NextResponse.json(
      {
        success: false,
        error: {
          code: 'FETCH_ERROR',
          message: 'Failed to fetch stats snapshots',
          details: error instanceof Error ? error.message : 'Unknown error',
        },
      },
      { status: 500 }
    );
  }
}

