  'COLLECTION_FORKED',
  'COLLECTION_TOOL_ADDED',
  'AGENT_CREATED',
  'AGENT_FORKED',
  'AGENT_LIKED',
  'COLLECTION_LIKED',
] as const;

/**
 * GET /api/activity/public
 * Returns recent public activity for the homepage activity stream.
 * Cached for 30 seconds with stale-while-revalidate.
